// ============================================================
// Evaluate one XGBoost tree
// ============================================================

static inline float model1_eval_tree(
    const Model1Tree& tree,
    const float* features
) {

    int node = 0;

    while (true) {

        int left =
            tree.left[node];

        // ----------------------------------------------------
        // Leaf node
        // ----------------------------------------------------

        if (left == -1) {

            return tree.leaf[node];
        }


        // ----------------------------------------------------
        // Internal node
        // ----------------------------------------------------

        int feature_index =
            tree.feature[node];


        float value =
            features[feature_index];


        float threshold =
            tree.threshold[node];


        // ----------------------------------------------------
        // XGBoost split:
        //
        // if feature < threshold
        //     go left
        // else
        //     go right
        // ----------------------------------------------------

        if (value < threshold) {

            node =
                tree.left[node];

        }
        else {

            node =
                tree.right[node];
        }
    }
}


// ============================================================
// Model 1 prediction
// ============================================================

static inline float model1_predict(
    const float* features
) {

    float prediction =
        MODEL1_BASE_SCORE;


    for (
        int tree_index = 0;
        tree_index < MODEL1_NUM_TREES;
        tree_index++
    ) {

        prediction +=
            model1_eval_tree(
                MODEL1_TREES[tree_index],
                features
            );
    }


    return prediction;
}

